extension ChannelMessage: Equatable, Hashable {
    public static func ==(lhs: ChannelMessage, rhs: ChannelMessage) -> Bool {
        if lhs.data != rhs.data {
            return false
        }
        if lhs.last != rhs.last {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(data)
        hasher.combine(last)
    }
}



